/// `SwordSage` — apply 1 `SwordSage` to self, granting every Sovereign Blade
/// **Replay 1**.
///
/// C# v0.107.1 `SwordSage.OnPlay` applies `SwordSagePower(1)`;
/// `SwordSagePower.AfterPowerAmountChanged` then adds the amount delta to
/// every owned `SovereignBlade.BaseReplayCount` (and
/// `AfterCardEnteredCombat` syncs any blade forged later — see
/// `combat_forge`). A blade with `BaseReplayCount = N` re-resolves its play
/// `N` extra times via the engine replay loop. This replaced the v0.103.2
/// extra-HIT mechanism (`SwordSagePower.SetRepeats(Amount + 1)`).
pub(crate) fn play_sword_sage(state: &mut CombatState, _t: Option<CreatureUid>) -> EffectResult {
    apply_power_to_player(state, PowerKind::SwordSage, 1);
    // `SwordSagePower.AfterPowerAmountChanged`: bump the replay count of every
    // SovereignBlade the player currently owns (any pile, incl. exhaust) by the
    // applied delta (1). Blades forged AFTER this point are synced in
    // `combat_forge` (the `AfterCardEnteredCombat` analogue).
    for uid in collect_blade_uids(state, /* include_exhaust */ true) {
        let idx = uid.0.get() as usize - 1;
        if let Some(card) = state.cards.get_mut(idx) {
            card.base_replay_count = card.base_replay_count.saturating_add(1);
        }
    }
    EffectResult::Resolved
}

